head.script:
scwin.onpageload = function() {
    var row = 10;
    var col = 3;
    var data = [];
    for (var i = 0; i < row; i++) {
        for (var j = 0; j < col; j++) {
            data.push("data=" + i);
        }
    }
    dataList1.setData(data);
};
scwin.onpageunload = function() {};
scwin.dataList1_onbeforecelldatachange = function(info) {
    if (info.newValue == "22") {
        return false;
    } else {
        return true;
    }
};
scwin.dataMap1_onbeforemodelchange = function(info) {
    if (info.newValue == "22") {
        return false;
    } else {
        return true;
    }
};
scwin.dataMap1_onmodelchange = function(info) {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#input1', 'key-sequence', {
        sequence: '22'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#input1', 'key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('input1').value == ''", "true");
    WebSquare.wUnit.addCommand("pause", "400");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
